declare(strict_types=1);
define('WP_CLI',true);require __DIR__.'/bootstrap.php';
$service=$core->get('learning_subscriptions');$worker=$core->get('account_mail_worker');$saved=$service->snapshot();wp_set_current_user($admin);$service->saveConfig(['enabled'=>true,'paused'=>false],$saved['revision']);$f=get_option('aish_p14_newsletter_race');if(!is_array($f)||!isset($f['a'],$f['mail_a']))exit(5);
$name=get_userdata($f['a'])->user_login;$prefix=substr($name,0,-strlen('campaign-race-a'));$users=[];foreach(['owner','paused','chinese']as$suffix)$users[$suffix]=(int)$db->value('SELECT ID FROM '.$db->connection()->users.' WHERE user_login=%s',[$prefix.'campaign-'.$suffix]);
$find=fn(int$id):?array=>$db->row('SELECT * FROM '.$db->table('notification_outbox')." WHERE recipient_user_id=%d AND template_key='newsletter_weekly' ORDER BY id DESC LIMIT 1",[$id]);$read=fn(int$id):?array=>$db->row('SELECT * FROM '.$db->table('notification_outbox').' WHERE id=%d',[$id]);$messages=[];add_filter('pre_wp_mail',static function($v,$mail)use(&$messages){$messages[]=$mail;return true;},PHP_INT_MAX,2);
$send=function(int$id)use($db,$worker):void{$table=$db->table('notification_outbox');$db->execute("UPDATE $table SET available_at='1971-01-01 00:00:00' WHERE id=%d",[$id]);$select=static function(string$sql)use($table,$id):string{if(str_starts_with($sql,"SELECT * FROM $table WHERE status IN ('queued','retry')")&&str_ends_with($sql,' LIMIT 1 FOR UPDATE'))return str_replace(' ORDER BY ',' AND id='.(int)$id.' ORDER BY ',$sql);return$sql;};add_filter('query',$select,PHP_INT_MAX);try{$worker->run();}finally{remove_filter('query',$select,PHP_INT_MAX);}};
try{
p14_case('same_generation_digest_headers_and_live_public_gate',function()use($users,$find,$send,$read,&$messages,$db){$mail=$find($users['owner']);p14_assert($mail!==null,'Retained first-run owned digest exists');$before=count($messages);$send((int)$mail['id']);$r=$read((int)$mail['id']);p14_assert($r['status']==='accepted'&&count($messages)===$before+1,'Corrected test-only selector dispatches one existing digest');$m=end($messages);$headers=is_array($m['headers'])?implode("\n",$m['headers']):$m['headers'];p14_assert(str_contains($headers,'List-Unsubscribe:')&&str_contains($headers,'List-Unsubscribe-Post: List-Unsubscribe=One-Click'),'One-click cancellation headers retained');p14_assert(str_contains($m['message'],'Unsubscribe:'),'Bilingual body includes cancellation');$archived=$db->rows('SELECT tr.title FROM '.$db->table('skills').' s INNER JOIN '.$db->table('skill_translations')." tr ON tr.skill_id=s.id WHERE s.status='archived' AND tr.locale='en_US' AND tr.title LIKE %s",['%campaign-public-5%']);foreach($archived as$item)p14_assert(!str_contains($m['message'],$item['title']),'Archived source removed from old approved campaign before transport');});
p14_case('global_pause_defers_same_row_and_resume_preserves_attempt_budget',function()use($service,$users,$find,$send,$read,&$messages){$mail=$find($users['paused']);$service->saveConfig(['enabled'=>true,'paused'=>true],$service->snapshot()['revision']);$before=count($messages);$send((int)$mail['id']);$r=$read((int)$mail['id']);p14_assert(in_array($r['status'],['queued','retry'],true)&&$r['payload_ciphertext']!==null&&count($messages)===$before,'Real pause defers existing encrypted message');p14_assert((int)$r['attempts']===0,'Deferral returns transport attempt budget');$service->saveConfig(['enabled'=>true,'paused'=>false],$service->snapshot()['revision']);$send((int)$mail['id']);p14_assert($read((int)$mail['id'])['status']==='accepted','Resume accepts same retained digest once');});
p14_case('chinese_issue_reuses_curated_content_and_only_selected_language',function()use($users,$find,$send,$read,&$messages){$mail=$find($users['chinese']);p14_assert($mail!==null&&$mail['locale']==='zh_CN','Retained Chinese digest belongs to Chinese subscriber');$send((int)$mail['id']);p14_assert($read((int)$mail['id'])['status']==='accepted','Chinese transport intercepted acceptance');$m=end($messages);p14_assert(str_contains($m['subject'],'每周精选')&&str_contains($m['message'],'/zh/')&&str_contains($m['message'],'取消订阅'),'Chinese message uses Chinese source and cancellation URLs');});
}finally{$service->saveConfig(array_intersect_key($saved,['enabled'=>true,'paused'=>true]),$service->snapshot()['revision']);}
